  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$ select "better_supabase"."list_file_comments"($1, $2) $function$;

CREATE OR REPLACE FUNCTION api.messaging_file_anchor_valid (
